#!/usr/bin/env python3
"""Convert a trail body_document.content_json (TipTap/ProseMirror) to markdown.

Handles the node/mark types actually present in this document: doc, heading,
paragraph, codeBlock, bulletList, orderedList, listItem, text with code/bold/
italic/link marks.
"""
import json
import sys


def inline(nodes):
    out = []
    for n in nodes or []:
        if n.get("type") != "text":
            # hardBreak or anything else inline
            if n.get("type") == "hardBreak":
                out.append("\n")
            continue
        text = n.get("text", "")
        marks = {m.get("type"): m for m in n.get("marks", []) or []}
        if "code" in marks:
            # Avoid doubling backticks if the text already carries them.
            text = f"`{text}`" if "`" not in text else text
        if "bold" in marks or "strong" in marks:
            text = f"**{text}**"
        if "italic" in marks or "em" in marks:
            text = f"*{text}*"
        if "link" in marks:
            href = (marks["link"].get("attrs") or {}).get("href", "")
            if href:
                text = f"[{text}]({href})"
        out.append(text)
    return "".join(out)


def block(node, depth=0, ordinal=None):
    t = node.get("type")
    content = node.get("content") or []

    if t == "heading":
        level = (node.get("attrs") or {}).get("level", 2)
        return [f"{'#' * level} {inline(content)}"]

    if t == "paragraph":
        text = inline(content)
        return [text] if text.strip() else []

    if t == "codeBlock":
        lang = (node.get("attrs") or {}).get("language") or ""
        body = inline(content)
        return [f"```{lang}\n{body}\n```"]

    if t in ("bulletList", "orderedList"):
        lines = []
        for i, item in enumerate(content, start=1):
            marker = f"{i}." if t == "orderedList" else "-"
            inner = []
            for child in item.get("content") or []:
                inner.extend(block(child, depth + 1))
            if not inner:
                continue
            pad = "  " * depth
            lines.append(f"{pad}{marker} {inner[0]}")
            for extra in inner[1:]:
                lines.append(f"{pad}  {extra}")
        return lines

    if t == "blockquote":
        lines = []
        for child in content:
            for line in block(child, depth):
                lines.append(f"> {line}")
        return lines

    # Unknown container: recurse.
    lines = []
    for child in content:
        lines.extend(block(child, depth))
    return lines


def main():
    doc = json.load(sys.stdin)
    blocks = []
    for node in doc.get("content") or []:
        blocks.extend(block(node))
    print("\n\n".join(blocks))


if __name__ == "__main__":
    main()

