// TestShadowStrategy_Rewind_PreservesIgnoredAndUntrackedFiles guards the
// restore path against wiping files git never tracked. Rewind writes the
// checkpoint tree over the worktree; if it ever reaches for go-git's
// Worktree.Reset/Checkout instead, those delete ignored directories even when
// .gitignore lists them (see the Git Operations section in CLAUDE.md), which
// would take out `.entire/` — the session state and logs the CLI needs to keep
// working after the restore.
//
// The other Rewind tests here assert the checkpoint's own files come back;
// PreviewRewind covers which untracked files are *planned* for deletion. This
// one covers what survives an actual execution, which is the half where the
// go-git hazard lives.
func TestShadowStrategy_Rewind_PreservesIgnoredAndUntrackedFiles(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	repo, err := git.PlainOpen(dir)
